#' @title Get survey forms
#' @description
#' Get the survey form definition for a specific survey form from SurveyCTO via API.  This form is a wrapper for `rsurveycto::scto_get_form_definitions()`.
#'
#' @param .formid a character string that identifies the SurveyCTO form
#' @param .auth an authorization block generated by `rsurveycto::scto_auth()`
#'
#' @return A list object that corresponds to the sheets of survey form from SurveyCTO, which are typically downloaded as XLSX files. Class data.frame and data.table. The list has four elements: `settings`, `choices`, `fields`, and `formulasConvertedToStaticValues`.
#' @export
#'
#' @examples NULL
scto_form <- function(.formid, .auth) {
  if (!check_scto_api(.auth)) stop(".auth must be an scto_auth object.", call. = FALSE)
  if (!is.character(.formid) || length(.formid) != 1L || is.na(.formid) || !nzchar(.formid))
    stop(".formid must be a non-empty character string.", call. = FALSE)
  if (!requireNamespace("rsurveycto", quietly = TRUE))
    stop("Install rsurveycto to use API downloads; local files do not require it.", call. = FALSE)
  rsurveycto::scto_get_form_definitions(auth = .auth, form_ids = .formid)
}
